      },
      {
        "op": "eq",
        "lhs": "$basket.store_id",
        "rhs": "$store.store_id",
        "args": []
      }
    ]
  },
  "answer_shape": {
    "msg_skeleton": "Applied {discount_percent}% service recovery discount to basket {basket_id} at {store_name}.",
    "kind": "",
    "columns": [],
    "rows_from": ""
